--
-- Table structure for table `invoice`
--

DROP TABLE IF EXISTS `invoice`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `invoice` (
  `id` int NOT NULL AUTO_INCREMENT,
  `branchId` int NOT NULL,
  `customerId` int NOT NULL,
  `invoiceNo` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `invoiceDate` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `dueDate` datetime(3) DEFAULT NULL,
  `status` enum('DRAFT','PAID','DUE','PARTIALLY_PAID','OVERDUE','CANCELLED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'DRAFT',
  `subtotal` decimal(14,2) NOT NULL,
  `discountAmount` decimal(14,2) NOT NULL DEFAULT '0.00',
  `taxAmount` decimal(14,2) NOT NULL DEFAULT '0.00',
  `deliveryAmount` decimal(14,2) NOT NULL DEFAULT '0.00',
  `grandTotal` decimal(14,2) NOT NULL,
  `paidAmount` decimal(14,2) NOT NULL DEFAULT '0.00',
  `dueAmount` decimal(14,2) NOT NULL DEFAULT '0.00',
  `notes` text COLLATE utf8mb4_unicode_ci,
  `terms` text COLLATE utf8mb4_unicode_ci,
  `createdById` int DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `Invoice_branchId_invoiceNo_key` (`branchId`,`invoiceNo`),
  KEY `Invoice_branchId_status_invoiceDate_idx` (`branchId`,`status`,`invoiceDate`),
  KEY `Invoice_customerId_status_idx` (`customerId`,`status`)
) ENGINE=InnoDB AUTO_INCREMENT=35 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
