DROP TABLE IF EXISTS `particular`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `particular` (
  `id` int NOT NULL AUTO_INCREMENT,
  `branchId` int NOT NULL,
  `employeeId` int DEFAULT NULL,
  `ledgerId` int NOT NULL,
  `salary` double NOT NULL DEFAULT '0',
  `type` enum('Credit','Debit') COLLATE utf8mb4_unicode_ci NOT NULL,
  `balance` double NOT NULL,
  `openingBalance` double NOT NULL,
  `openingBalanceType` enum('Credit','Debit') COLLATE utf8mb4_unicode_ci NOT NULL,
  `openingBalanceDate` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `companyName` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `accountType` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `mobileNumber` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `email` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `address` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `Particular_ledgerId_fkey` (`ledgerId`),
  CONSTRAINT `Particular_ledgerId_fkey` FOREIGN KEY (`ledgerId`) REFERENCES `ledger` (`id`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=136 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
